begin;
do $qa$
declare actor uuid; app public.oneul_applications; page uuid; info jsonb; result jsonb; snapshot jsonb;
begin
 select user_id into actor from public.oneul_staff limit 1;
 if actor is null then raise exception 'QA requires an existing operator'; end if;
 if exists(select 1 from public.oneul_applications where event_date='2030-12-21' and start_time='13:00') then raise exception 'QA cohort occupied'; end if;
 insert into public.oneul_applications(source,external_order_no,name,phone,gender,event_date,start_time,amount,status,profile,submitted_at,confirmed_at,confirmed_by,expires_at)
 values('frip','__qa_qr_view_'||gen_random_uuid(),'QR 재확인 검증','+821000000000','남성','2030-12-21','13:00',1000,'confirmed','{}',now(),now(),actor,now()+interval '30 days') returning * into app;
 begin perform public.oneul_memo_qr_info(app.id,actor);raise exception using errcode='PZ002',message='Unissued QR returned';exception when no_data_found then null;end;
 result:=public.oneul_memo_issue(app.id,actor,repeat('1',64),13,1,app.updated_at,false);page:=(result->>'pageId')::uuid;
 perform public.oneul_memo_exchange_qr(repeat('1',64),repeat('2',64));
 perform public.oneul_memo_save(repeat('2',64),page,1,'저장된 메모 유지',2,0,gen_random_uuid());
 perform public.oneul_matching_save(repeat('2',64),page,array[1,3],0,3,gen_random_uuid());
 snapshot:=public.oneul_memo_read(repeat('2',64),page);
 execute 'set local role service_role';
 info:=public.oneul_memo_qr_info(app.id,actor);
 if info->>'qrHash'<>repeat('1',64) then raise exception 'Canonical binding missing'; end if;
 result:=public.oneul_memo_qr_register(app.id,actor,repeat('3',64),info->>'qrHash');
 if result->>'retrieved'<>'true' or result ? 'qrHash' then raise exception 'Invalid retrieval receipt'; end if;
 perform public.oneul_memo_qr_register(app.id,actor,repeat('3',64),info->>'qrHash');
 if (select count(*) from oneul_private.memo_qr_retrievals where page_id=page)<>1 then raise exception 'Repeated view duplicated QR'; end if;
 perform public.oneul_memo_exchange_qr(repeat('1',64),repeat('4',64));
 perform public.oneul_memo_exchange_qr(repeat('3',64),repeat('5',64));
 if public.oneul_memo_read(repeat('5',64),page)<>snapshot or public.oneul_memo_read(repeat('2',64),page)<>snapshot then raise exception 'Viewing QR changed notes, choices or existing session'; end if;
 begin perform public.oneul_memo_qr_register(app.id,actor,repeat('6',64),repeat('7',64));raise exception using errcode='PZ002',message='Stale canonical accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.oneul_memo_qr_info(app.id,gen_random_uuid());raise exception using errcode='PZ002',message='Nonstaff actor accepted';exception when insufficient_privilege then null;end;
 execute 'reset role';
 execute 'set local role authenticated';
 begin perform public.oneul_memo_qr_info(app.id,actor);raise exception using errcode='PZ002',message='Browser role reached service RPC';exception when insufficient_privilege then null;end;
 begin perform public.oneul_memo_qr_register(app.id,actor,repeat('6',64),repeat('1',64));raise exception using errcode='PZ002',message='Browser role registered QR';exception when insufficient_privilege then null;end;
 execute 'reset role';
 update public.oneul_applications set start_time='16:00' where id=app.id;
 begin perform public.oneul_memo_qr_info(app.id,actor);raise exception using errcode='PZ002',message='Changed cohort accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.oneul_memo_exchange_qr(repeat('3',64),repeat('6',64));raise exception using errcode='PZ002',message='Changed cohort scanned';exception when invalid_authorization_specification then null;end;
 update public.oneul_applications set start_time='13:00' where id=app.id;
 update oneul_private.memo_pages set expires_at=now()-interval '1 minute' where id=page;
 begin perform public.oneul_memo_qr_info(app.id,actor);raise exception using errcode='PZ002',message='Expired QR viewed';exception when invalid_authorization_specification then null;end;
 begin perform public.oneul_memo_exchange_qr(repeat('3',64),repeat('6',64));raise exception using errcode='PZ002',message='Expired QR scanned';exception when invalid_authorization_specification then null;end;
 update oneul_private.memo_pages set expires_at=now()+interval '30 days' where id=page;
 update public.oneul_applications set status='canceled' where id=app.id;
 begin perform public.oneul_memo_qr_info(app.id,actor);raise exception using errcode='PZ002',message='Canceled QR viewed';exception when invalid_authorization_specification then null;end;
 begin perform public.oneul_memo_exchange_qr(repeat('3',64),repeat('6',64));raise exception using errcode='PZ002',message='Canceled QR scanned';exception when invalid_authorization_specification then null;end;
 update public.oneul_applications set status='confirmed' where id=app.id returning * into app;
 perform public.oneul_memo_issue(app.id,actor,repeat('8',64),13,1,app.updated_at,true);
 begin perform public.oneul_memo_exchange_qr(repeat('3',64),repeat('6',64));raise exception using errcode='PZ002',message='Reissued alias remained valid';exception when invalid_authorization_specification then null;end;
 begin perform public.oneul_memo_read(repeat('2',64),page);raise exception using errcode='PZ002',message='Reissued session remained valid';exception when invalid_authorization_specification then null;end;
 perform public.oneul_memo_qr_register(app.id,actor,repeat('9',64),repeat('8',64));
 perform public.oneul_memo_exchange_qr(repeat('9',64),repeat('a',64));
 if public.oneul_memo_read(repeat('a',64),page)->'entries'<>snapshot->'entries' then raise exception 'Reissue lost notes'; end if;
 if (select numbers from oneul_private.matching_submissions where page_id=page)<>array[1,3] then raise exception 'Reissue lost matching choices'; end if;
 delete from public.oneul_applications where id=app.id;
 if exists(select 1 from oneul_private.memo_qr_retrievals where page_id=page) then raise exception 'Retrieval rows did not cascade'; end if;
end $qa$;
rollback;
select count(*) as synthetic_records_remaining from public.oneul_applications where external_order_no like '__qa_qr_view_%';
